from torch.utils.checkpoint import checkpoint

class BigBlock(nn.Module):
    def __init__(self):
        super().__init__()
        self.seq = nn.Sequential(*[nn.Linear(512,512) for _ in range(5)])
    def forward(self, x):
        return checkpoint(self.seq, x, use_reentrant=False)

block = BigBlock()
x = torch.randn(2,512)
out = block(x)
print(out.shape)
